			draw=none, line width=1pt, smooth]{0};
	    \addplot[blue!40!white, fill opacity=0.5] fill between [of=f and g]; 
\end{scope}

\end{axis}

\node[left] at (0.8,1.75) {$P(Z < -\z)$};
\draw[-latex, line width=0.6, samples=200] 
	(0.8,1.75) to [bend left=30] (1.4,1.1);

